      return res.json();
    },
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ["/api/duplicates"] });
      toast({
        title: "Scan Complete",
        description: `Found ${data.scannedCount} potential duplicates`,
      });
