          <Button
            variant={filter === "all" ? "default" : "outline"}
            onClick={() => setFilter("all")}
            data-testid="button-filter-all"
          >
            All
            <Badge variant="secondary" className="ml-2">
              {candidates.length}
            </Badge>
          </Button>
        </div>

        {/* Duplicates Table */}
        <DuplicatesTable
          candidates={candidates}
          isLoading={isLoading}
        />
      </div>
    </div>
  );
}

