import { useQuery, useMutation } from "@tanstack/react-query";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { useToast } from "@/hooks/use-toast";
import { Trash2, Smartphone } from "lucide-react";
import { formatDistanceToNow } from "date-fns";

interface TrustedDevice {
  id: string;
  label: string;
  expiresAt: string;
  lastUsedAt: string;
  createdAt: string;
}

export default function DevicesPage() {
  const { toast } = useToast();

  const { data, isLoading } = useQuery<{ devices: TrustedDevice[] }>({
    queryKey: ["/api/auth/trusted-devices"],
  });

  const revokeMutation = useMutation({
    mutationFn: async (deviceId: string) => {
      await apiRequest("DELETE", `/api/auth/trusted-devices/${deviceId}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/auth/trusted-devices"] });
      toast({
        title: "Device revoked",
        description: "This device will require 2FA verification on next login.",
      });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Failed to revoke device",
        variant: "destructive",
      });
    },
  });

  const devices = data?.devices || [];

  return (
    <div className="container mx-auto py-8 max-w-4xl">
      <div className="mb-6">
        <h1 className="text-3xl font-bold mb-2" data-testid="text-page-title">
          Trusted Devices
        </h1>
        <p className="text-muted-foreground">
          Manage devices that can skip 2FA verification. Trusted devices remain valid for 30 days from last use.
        </p>
      </div>

      {isLoading ? (
        <div className="space-y-4">
          <Skeleton className="h-32 w-full" />
          <Skeleton className="h-32 w-full" />
        </div>
      ) : devices.length === 0 ? (
        <Card data-testid="card-no-devices">
          <CardContent className="pt-6">
            <div className="text-center py-8">
              <Smartphone className="mx-auto h-12 w-12 text-muted-foreground mb-4" />
              <h3 className="text-lg font-semibold mb-2">No trusted devices</h3>
              <p className="text-muted-foreground">
                When you enable "Trust this device" during 2FA verification, it will appear here.
              </p>
            </div>
          </CardContent>
        </Card>
      ) : (
        <div className="space-y-4">
          {devices.map((device) => (
            <Card key={device.id} data-testid={`card-device-${device.id}`}>
              <CardHeader>
                <div className="flex items-start justify-between">
                  <div className="flex items-center gap-3">
                    <Smartphone className="h-5 w-5 text-primary" />
                    <div>
                      <CardTitle className="text-lg" data-testid={`text-device-label-${device.id}`}>
                        {device.label}
                      </CardTitle>
                      <CardDescription>
                        <div className="space-y-1 mt-1">
                          <div data-testid={`text-device-created-${device.id}`}>
                            Added {formatDistanceToNow(new Date(device.createdAt), { addSuffix: true })}
                          </div>
                          <div data-testid={`text-device-lastused-${device.id}`}>
                            Last used {formatDistanceToNow(new Date(device.lastUsedAt), { addSuffix: true })}
                          </div>
                          <div data-testid={`text-device-expires-${device.id}`}>
                            Expires {formatDistanceToNow(new Date(device.expiresAt), { addSuffix: true })}
                          </div>
                        </div>
                      </CardDescription>
                    </div>
                  </div>
                  <Button
                    variant="ghost"
                    size="icon"
                    onClick={() => revokeMutation.mutate(device.id)}
                    disabled={revokeMutation.isPending}
                    data-testid={`button-revoke-${device.id}`}
                  >
                    <Trash2 className="h-4 w-4" />
                  </Button>
                </div>
              </CardHeader>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

config/featureFlags.ts.content:
/**
 * Feature Flags Configuration
 * 
 * Centralized feature toggle system for enabling/disabling features
 * without code changes. Useful for A/B testing, gradual rollouts, and
 * emergency kill switches.
 */

export interface FeatureFlagConfig {
  enabled: boolean;
  description: string;
  rolloutPercentage?: number; // 0-100, for gradual rollouts
  allowlist?: string[]; // User IDs or emails for early access
}

export const featureFlags = {
  /**
   * Core Features
   */
  scraping: {
    enabled: true,
    description: "Arrest record scraping via Python scraper",
  } as FeatureFlagConfig,

  aiEnrichment: {
    enabled: true,
    description: "OpenAI GPT-4o-mini charge classification and risk scoring",
  } as FeatureFlagConfig,

  leadScoring: {
    enabled: true,
    description: "Automated lead scoring (0-100 scale)",
  } as FeatureFlagConfig,

  deduplication: {
    enabled: true,
    description: "Fuzzy matching duplicate detection",
  } as FeatureFlagConfig,

  analytics: {
    enabled: true,
    description: "Analytics dashboard with Recharts visualizations",
  } as FeatureFlagConfig,

  /**
   * CRM Features
   */
  crmProspects: {
    enabled: true,
    description: "CRM prospect management",
  } as FeatureFlagConfig,

  phantombusterIntegration: {
    enabled: true,
    description: "PhantomBuster LinkedIn/Facebook prospect discovery",
  } as FeatureFlagConfig,

  calendlyIntegration: {
    enabled: true,
    description: "Calendly meeting scheduling",
  } as FeatureFlagConfig,

  googleSheetsIntegration: {
    enabled: true,
    description: "Google Sheets bi-directional sync",
  } as FeatureFlagConfig,

  /**
   * Export Features
   */
  csvExport: {
    enabled: true,
    description: "CSV export for arrest records",
  } as FeatureFlagConfig,

  jsonExport: {
    enabled: true,
    description: "JSON export for arrest records",
  } as FeatureFlagConfig,

  /**
   * Experimental Features (Beta)
   */
  scheduledScraping: {
    enabled: false,
    description: "[BETA] Automated scheduled scraping via cron",
    rolloutPercentage: 0,
  } as FeatureFlagConfig,

  automatedOutreach: {
    enabled: false,
    description: "[BETA] Automated email outreach sequences",
    rolloutPercentage: 0,
  } as FeatureFlagConfig,

  webhookSupport: {
    enabled: false,
    description: "[BETA] Webhook callbacks for job completion",
    rolloutPercentage: 0,
  } as FeatureFlagConfig,

  multiTenant: {
    enabled: false,
    description: "[BETA] Multi-tenant support for agencies",
    rolloutPercentage: 0,
  } as FeatureFlagConfig,
};

/**
 * Check if a feature is enabled
 */
export function isFeatureEnabled(
  featureName: keyof typeof featureFlags,
  userId?: string
): boolean {
  const flag = featureFlags[featureName];

  if (!flag || !flag.enabled) {
    return false;
  }

  // If allowlist exists, check if user is in it
  if (flag.allowlist && userId) {
    return flag.allowlist.includes(userId);
  }

  // If rollout percentage is set, use it for gradual rollout
  if (flag.rolloutPercentage !== undefined) {
    if (flag.rolloutPercentage === 0) return false;
    if (flag.rolloutPercentage === 100) return true;

    // Use userId to determine if user is in rollout
    if (userId) {
      const hash = hashUserId(userId);
      return hash % 100 < flag.rolloutPercentage;
    }

    // No userId provided, default to disabled
    return false;
  }

  return true;
}

/**
 * Simple hash function for userId-based rollout
 */
function hashUserId(userId: string): number {
  let hash = 0;
  for (let i = 0; i < userId.length; i++) {
    const char = userId.charCodeAt(i);
    hash = ((hash << 5) - hash) + char;
    hash = hash & hash; // Convert to 32-bit integer
  }
  return Math.abs(hash);
}

/**
 * Get all enabled features
 */
export function getEnabledFeatures(): string[] {
  return Object.entries(featureFlags)
    .filter(([_, config]) => config.enabled)
    .map(([name, _]) => name);
}

/**
 * Get feature flag configuration
 */
export function getFeatureFlag(featureName: keyof typeof featureFlags): FeatureFlagConfig | undefined {
  return featureFlags[featureName];
}

/**
 * Example usage:
 * 
 * ```typescript
 * import { isFeatureEnabled } from '@/config/featureFlags';
 * 
 * if (isFeatureEnabled('aiEnrichment')) {
 *   await enhanceRecordsWithAI(records);
 * }
 * 
 * // With user-specific rollout
 * if (isFeatureEnabled('scheduledScraping', userId)) {
 *   showSchedulingUI();
 * }
 * ```
 */

