import { useState, useEffect } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";
import { Calendar, Clock, CheckCircle2, Loader2 } from "lucide-react";

interface AppointmentBookingDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  sessionId?: string | null;
  arrestRecordId?: string | null;
}

interface AvailableSlot {
  id: string;
  startTime: string;
  endTime: string;
  duration: number;
  timezone: string;
  available: boolean;
  remainingSlots: number;
}

export function AppointmentBookingDialog({
  open,
  onOpenChange,
  sessionId,
  arrestRecordId,
}: AppointmentBookingDialogProps) {
  const { toast } = useToast();
  const [selectedDate, setSelectedDate] = useState(() => {
    const today = new Date();
    return today.toISOString().split("T")[0];
  });
  const [selectedSlot, setSelectedSlot] = useState<AvailableSlot | null>(null);
  const [bookingComplete, setBookingComplete] = useState(false);
  const [userTimezone] = useState(() => {
    try {
      return Intl.DateTimeFormat().resolvedOptions().timeZone;
    } catch {
      return "America/New_York";
    }
  });

  const { data: availabilityData, isLoading: availabilityLoading } = useQuery<{
    date: string;
    dayOfWeek: number;
    slots: AvailableSlot[];
  }>({
    queryKey: [`/api/appointments/availability?date=${selectedDate}`],
    enabled: open && !!selectedDate,
  });

  const bookingMutation = useMutation({
    mutationFn: async (data: any) => {
      const response = await apiRequest("POST", "/api/appointments/book", data);
      return response;
    },
    onSuccess: () => {
      setBookingComplete(true);
      toast({
        title: "Appointment Booked!",
        description: "Your appointment has been confirmed. We'll send you a reminder.",
      });
    },
    onError: (error: Error) => {
      toast({
        title: "Booking Failed",
        description: error.message || "Failed to book appointment. Please try again.",
        variant: "destructive",
      });
    },
  });

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!selectedSlot) {
      toast({
        title: "No Slot Selected",
        description: "Please select an available time slot",
        variant: "destructive",
      });
      return;
    }

    const formData = new FormData(e.currentTarget);

    bookingMutation.mutate({
      slotId: selectedSlot.id,
      appointmentDate: selectedDate,
      appointmentTime: formData.get("appointmentTime") as string,
      visitorName: formData.get("visitorName") as string,
      visitorEmail: formData.get("visitorEmail") as string,
      visitorPhone: formData.get("visitorPhone") as string || undefined,
      visitorTimezone: userTimezone,
      caseType: formData.get("caseType") as string || undefined,
      notes: formData.get("notes") as string || undefined,
      sessionId: sessionId || undefined,
      arrestRecordId: arrestRecordId || undefined,
    });
  };

  const handleClose = () => {
    setBookingComplete(false);
    setSelectedSlot(null);
    onOpenChange(false);
  };

  useEffect(() => {
    if (!open) {
      setBookingComplete(false);
      setSelectedSlot(null);
    }
  }, [open]);

  const availableSlots = availabilityData?.slots || [];
  const hasAvailability = availableSlots.length > 0;

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto" data-testid="dialog-appointment-booking">
        {bookingComplete ? (
          <>
            <DialogHeader>
              <div className="flex items-center gap-2">
                <CheckCircle2 className="h-6 w-6 text-green-600" />
                <DialogTitle>Appointment Confirmed!</DialogTitle>
              </div>
              <DialogDescription>
                Your appointment has been successfully scheduled.
              </DialogDescription>
            </DialogHeader>
            <div className="space-y-4 py-4">
              <Card className="p-4 bg-muted">
                <div className="space-y-2">
                  <p className="text-sm">
                    <span className="font-semibold">Date:</span> {selectedDate}
                  </p>
                  <p className="text-sm">
                    <span className="font-semibold">Time:</span> {selectedSlot?.startTime} ({userTimezone})
                  </p>
                  {sessionId && (
                    <div className="flex items-center gap-2 mt-2">
                      <Badge variant="secondary" className="text-xs">
                        Linked to chat session
                      </Badge>
                    </div>
                  )}
                </div>
              </Card>
              <p className="text-sm text-muted-foreground">
                A confirmation has been recorded. We'll send you a reminder before your appointment.
              </p>
            </div>
            <DialogFooter>
              <Button onClick={handleClose} data-testid="button-close-confirmation">
                Close
              </Button>
            </DialogFooter>
          </>
        ) : (
          <>
            <DialogHeader>
              <DialogTitle className="flex items-center gap-2">
                <Calendar className="h-5 w-5" />
                Schedule an Appointment
              </DialogTitle>
              <DialogDescription>
                Select a date and time that works for you. Timezone: {userTimezone}
              </DialogDescription>
              {sessionId && (
                <Badge variant="secondary" className="w-fit" data-testid="badge-linked-session">
                  Linked to current chat session
                </Badge>
              )}
            </DialogHeader>

            <form onSubmit={handleSubmit}>
              <div className="space-y-4 py-4">
                <div className="space-y-2">
                  <Label htmlFor="appointmentDate">Date</Label>
                  <Input
                    id="appointmentDate"
                    type="date"
                    value={selectedDate}
                    onChange={(e) => {
                      setSelectedDate(e.target.value);
                      setSelectedSlot(null);
                    }}
                    min={new Date().toISOString().split("T")[0]}
                    required
                    data-testid="input-appointment-date"
                  />
                </div>

                <div className="space-y-2">
                  <Label>Available Time Slots</Label>
                  {availabilityLoading ? (
                    <div className="flex items-center gap-2 text-sm text-muted-foreground">
                      <Loader2 className="h-4 w-4 animate-spin" />
                      Loading availability...
                    </div>
                  ) : !hasAvailability ? (
                    <p className="text-sm text-muted-foreground">
                      No available slots for this date. Please select another date.
                    </p>
                  ) : (
                    <div className="grid grid-cols-3 gap-2" data-testid="grid-time-slots">
                      {availableSlots.map((slot) => (
                        <Button
                          key={slot.id}
                          type="button"
                          variant={selectedSlot?.id === slot.id ? "default" : "outline"}
                          onClick={() => setSelectedSlot(slot)}
                          className="flex items-center gap-2"
                          data-testid={`button-slot-${slot.id}`}
                        >
                          <Clock className="h-3 w-3" />
                          {slot.startTime}
                        </Button>
                      ))}
                    </div>
                  )}
                </div>

                {selectedSlot && (
                  <>
                    <input
                      type="hidden"
                      name="appointmentTime"
                      value={selectedSlot.startTime}
                    />

                    <div className="space-y-4 pt-4 border-t">
                      <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                          <Label htmlFor="visitorName">Full Name *</Label>
                          <Input
                            id="visitorName"
                            name="visitorName"
                            placeholder="John Doe"
                            required
                            data-testid="input-visitor-name"
                          />
                        </div>
                        <div className="space-y-2">
                          <Label htmlFor="visitorEmail">Email *</Label>
                          <Input
                            id="visitorEmail"
                            name="visitorEmail"
                            type="email"
                            placeholder="john@example.com"
                            required
                            data-testid="input-visitor-email"
                          />
                        </div>
                      </div>

                      <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                          <Label htmlFor="visitorPhone">Phone (Optional)</Label>
                          <Input
                            id="visitorPhone"
                            name="visitorPhone"
                            type="tel"
                            placeholder="(555) 123-4567"
                            data-testid="input-visitor-phone"
                          />
                        </div>
                        <div className="space-y-2">
                          <Label htmlFor="caseType">Case Type (Optional)</Label>
                          <Select name="caseType">
                            <SelectTrigger data-testid="select-case-type">
                              <SelectValue placeholder="Select type" />
                            </SelectTrigger>
                            <SelectContent>
                              <SelectItem value="DUI">DUI</SelectItem>
                              <SelectItem value="Traffic">Traffic</SelectItem>
                              <SelectItem value="Criminal">Criminal Defense</SelectItem>
                              <SelectItem value="Consultation">General Consultation</SelectItem>
                              <SelectItem value="Other">Other</SelectItem>
                            </SelectContent>
                          </Select>
                        </div>
                      </div>

                      <div className="space-y-2">
                        <Label htmlFor="notes">Additional Notes (Optional)</Label>
                        <Textarea
                          id="notes"
                          name="notes"
                          placeholder="Any additional information we should know..."
                          rows={3}
                          data-testid="input-notes"
                        />
                      </div>
                    </div>
                  </>
                )}
              </div>

              <DialogFooter>
                <Button
                  type="button"
                  variant="outline"
                  onClick={handleClose}
                  data-testid="button-cancel-booking"
                >
                  Cancel
                </Button>
                <Button
                  type="submit"
                  disabled={!selectedSlot || bookingMutation.isPending}
                  data-testid="button-confirm-booking"
                >
                  {bookingMutation.isPending ? (
                    <>
                      <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                      Booking...
                    </>
                  ) : (
                    "Confirm Booking"
                  )}
                </Button>
              </DialogFooter>
            </form>
          </>
        )}
      </DialogContent>
    </Dialog>
  );
}

client/src/pages/admin/calendar.tsx.content:
import { useQuery, useMutation } from "@tanstack/react-query";
import { useState } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Switch } from "@/components/ui/switch";
import { useToast } from "@/hooks/use-toast";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { Plus, Edit, Trash2, Calendar, Clock } from "lucide-react";
import type { AppointmentSlot, AppointmentBooking } from "@shared/schema";

const DAYS_OF_WEEK = [
  { value: 0, label: "Sunday" },
  { value: 1, label: "Monday" },
  { value: 2, label: "Tuesday" },
  { value: 3, label: "Wednesday" },
  { value: 4, label: "Thursday" },
  { value: 5, label: "Friday" },
  { value: 6, label: "Saturday" },
];

const TIMEZONES = [
  "America/New_York",
  "America/Chicago",
  "America/Denver",
  "America/Los_Angeles",
  "America/Phoenix",
  "America/Anchorage",
  "Pacific/Honolulu",
];

export default function AdminCalendar() {
  const { toast } = useToast();
  const [isCreateOpen, setIsCreateOpen] = useState(false);
  const [editingSlot, setEditingSlot] = useState<AppointmentSlot | null>(null);

  const { data: slotsData, isLoading: slotsLoading } = useQuery<{ slots: AppointmentSlot[] }>({
    queryKey: ["/api/appointments/admin/slots"],
  });

  const { data: bookingsData, isLoading: bookingsLoading } = useQuery<{ bookings: AppointmentBooking[] }>({
    queryKey: ["/api/appointments/bookings"],
  });

  const createSlotMutation = useMutation({
    mutationFn: (data: any) => apiRequest("POST", "/api/appointments/admin/slots", data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/appointments/admin/slots"] });
      setIsCreateOpen(false);
      toast({
        title: "Success",
        description: "Appointment slot created successfully",
      });
    },
    onError: (error: Error) => {
      toast({
        title: "Error",
        description: error.message || "Failed to create slot",
        variant: "destructive",
      });
    },
  });

  const updateSlotMutation = useMutation({
    mutationFn: ({ id, data }: { id: string; data: any }) => apiRequest("PUT", `/api/appointments/admin/slots/${id}`, data),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/appointments/admin/slots"] });
      setEditingSlot(null);
      toast({
        title: "Success",
        description: "Appointment slot updated successfully",
      });
    },
    onError: (error: Error) => {
      toast({
        title: "Error",
        description: error.message || "Failed to update slot",
        variant: "destructive",
      });
    },
  });

  const deleteSlotMutation = useMutation({
    mutationFn: (id: string) => apiRequest("DELETE", `/api/appointments/admin/slots/${id}`),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/appointments/admin/slots"] });
      toast({
        title: "Success",
        description: "Appointment slot deleted successfully",
      });
    },
    onError: (error: Error) => {
      toast({
        title: "Error",
        description: error.message || "Failed to delete slot",
        variant: "destructive",
      });
    },
  });

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);

    const data = {
      dayOfWeek: parseInt(formData.get("dayOfWeek") as string),
      startTime: formData.get("startTime") as string,
      endTime: formData.get("endTime") as string,
      duration: parseInt(formData.get("duration") as string),
      timezone: formData.get("timezone") as string,
      isActive: formData.get("isActive") === "on" ? 1 : 0,
      maxBookings: parseInt(formData.get("maxBookings") as string),
    };

    if (editingSlot) {
      updateSlotMutation.mutate({ id: editingSlot.id, data });
    } else {
      createSlotMutation.mutate(data);
    }
  };

  const slots = slotsData?.slots || [];
  const bookings = bookingsData?.bookings || [];

  const slotsByDay = DAYS_OF_WEEK.map((day) => ({
    ...day,
    slots: slots.filter((slot) => slot.dayOfWeek === day.value),
  }));

  const upcomingBookings = bookings.filter(
    (booking) => booking.status === "confirmed" && new Date(booking.appointmentDate) >= new Date()
  ).slice(0, 10);

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold" data-testid="text-admin-calendar-title">Appointment Calendar Management</h1>
          <p className="text-muted-foreground">Configure availability and manage bookings</p>
        </div>
        <Dialog open={isCreateOpen} onOpenChange={setIsCreateOpen}>
          <DialogTrigger asChild>
            <Button data-testid="button-create-slot">
              <Plus className="mr-2 h-4 w-4" />
              Create Slot
            </Button>
          </DialogTrigger>
          <SlotFormDialog
            onSubmit={handleSubmit}
            isPending={createSlotMutation.isPending}
            onCancel={() => setIsCreateOpen(false)}
          />
        </Dialog>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 space-y-4">
          <Card>
            <CardHeader>
              <CardTitle>Weekly Availability</CardTitle>
              <CardDescription>Manage appointment slots for each day of the week</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              {slotsLoading ? (
                <p className="text-muted-foreground">Loading slots...</p>
              ) : (
                slotsByDay.map((day) => (
                  <div key={day.value} className="space-y-2">
                    <div className="flex items-center gap-2">
                      <h3 className="font-semibold text-sm" data-testid={`text-day-${day.value}`}>{day.label}</h3>
                      <Badge variant="outline" data-testid={`badge-slot-count-${day.value}`}>
                        {day.slots.length} {day.slots.length === 1 ? "slot" : "slots"}
                      </Badge>
                    </div>

                    {day.slots.length === 0 ? (
                      <p className="text-sm text-muted-foreground pl-4">No slots configured</p>
                    ) : (
                      <div className="space-y-2 pl-4">
                        {day.slots.map((slot) => (
                          <Card key={slot.id} className="p-3" data-testid={`card-slot-${slot.id}`}>
                            <div className="flex items-center justify-between">
                              <div className="space-y-1">
                                <div className="flex items-center gap-2">
                                  <Clock className="h-4 w-4 text-muted-foreground" />
                                  <span className="font-medium" data-testid={`text-slot-time-${slot.id}`}>
                                    {slot.startTime} - {slot.endTime}
                                  </span>
                                  <Badge variant={slot.isActive === 1 ? "default" : "secondary"} data-testid={`badge-slot-status-${slot.id}`}>
                                    {slot.isActive === 1 ? "Active" : "Inactive"}
                                  </Badge>
                                </div>
                                <p className="text-sm text-muted-foreground">
                                  {slot.duration} min slots • Max {slot.maxBookings} booking{slot.maxBookings > 1 ? "s" : ""} • {slot.timezone}
                                </p>
                              </div>
                              <div className="flex items-center gap-2">
                                <Dialog open={editingSlot?.id === slot.id} onOpenChange={(open) => !open && setEditingSlot(null)}>
                                  <DialogTrigger asChild>
                                    <Button
                                      variant="ghost"
                                      size="icon"
                                      onClick={() => setEditingSlot(slot)}
                                      data-testid={`button-edit-slot-${slot.id}`}
                                    >
                                      <Edit className="h-4 w-4" />
                                    </Button>
                                  </DialogTrigger>
                                  <SlotFormDialog
                                    slot={slot}
                                    onSubmit={handleSubmit}
                                    isPending={updateSlotMutation.isPending}
                                    onCancel={() => setEditingSlot(null)}
                                  />
                                </Dialog>
                                <Button
                                  variant="ghost"
                                  size="icon"
                                  onClick={() => {
                                    if (confirm("Are you sure you want to delete this slot?")) {
                                      deleteSlotMutation.mutate(slot.id);
                                    }
                                  }}
                                  data-testid={`button-delete-slot-${slot.id}`}
                                >
                                  <Trash2 className="h-4 w-4" />
                                </Button>
                              </div>
                            </div>
                          </Card>
                        ))}
                      </div>
                    )}
                  </div>
                ))
              )}
            </CardContent>
          </Card>
        </div>

        <div className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Calendar className="h-5 w-5" />
                Upcoming Bookings
              </CardTitle>
              <CardDescription>Next {upcomingBookings.length} confirmed appointments</CardDescription>
            </CardHeader>
            <CardContent className="space-y-3">
              {bookingsLoading ? (
                <p className="text-sm text-muted-foreground">Loading bookings...</p>
              ) : upcomingBookings.length === 0 ? (
                <p className="text-sm text-muted-foreground">No upcoming bookings</p>
              ) : (
                upcomingBookings.map((booking) => (
                  <Card key={booking.id} className="p-3" data-testid={`card-booking-${booking.id}`}>
                    <div className="space-y-1">
                      <div className="flex items-center justify-between">
                        <span className="font-medium text-sm" data-testid={`text-booking-name-${booking.id}`}>
                          {booking.visitorName}
                        </span>
                        <Badge variant="outline" data-testid={`badge-booking-status-${booking.id}`}>
                          {booking.status}
                        </Badge>
                      </div>
                      <p className="text-xs text-muted-foreground">
                        {booking.appointmentDate} at {booking.appointmentTime}
                      </p>
                      {booking.caseType && (
                        <Badge variant="secondary" className="text-xs">
                          {booking.caseType}
                        </Badge>
                      )}
                    </div>
                  </Card>
                ))
              )}
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}

function SlotFormDialog({
  slot,
  onSubmit,
  isPending,
  onCancel,
}: {
  slot?: AppointmentSlot;
  onSubmit: (e: React.FormEvent<HTMLFormElement>) => void;
  isPending: boolean;
  onCancel: () => void;
}) {
  return (
    <DialogContent data-testid="dialog-slot-form">
      <DialogHeader>
        <DialogTitle>{slot ? "Edit Appointment Slot" : "Create Appointment Slot"}</DialogTitle>
        <DialogDescription>
          Configure the time slot availability for appointments
        </DialogDescription>
      </DialogHeader>
      <form onSubmit={onSubmit}>
        <div className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="dayOfWeek">Day of Week</Label>
            <Select name="dayOfWeek" defaultValue={slot?.dayOfWeek?.toString() || "1"}>
              <SelectTrigger data-testid="select-day-of-week">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {DAYS_OF_WEEK.map((day) => (
                  <SelectItem key={day.value} value={day.value.toString()}>
                    {day.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="startTime">Start Time</Label>
              <Input
                id="startTime"
                name="startTime"
                type="time"
                defaultValue={slot?.startTime || "09:00"}
                required
                data-testid="input-start-time"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="endTime">End Time</Label>
              <Input
                id="endTime"
                name="endTime"
                type="time"
                defaultValue={slot?.endTime || "17:00"}
                required
                data-testid="input-end-time"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="duration">Duration (minutes)</Label>
              <Input
                id="duration"
                name="duration"
                type="number"
                defaultValue={slot?.duration || 30}
                min={15}
                step={15}
                required
                data-testid="input-duration"
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="maxBookings">Max Bookings</Label>
              <Input
                id="maxBookings"
                name="maxBookings"
                type="number"
                defaultValue={slot?.maxBookings || 1}
                min={1}
                required
                data-testid="input-max-bookings"
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="timezone">Timezone</Label>
            <Select name="timezone" defaultValue={slot?.timezone || "America/New_York"}>
              <SelectTrigger data-testid="select-timezone">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {TIMEZONES.map((tz) => (
                  <SelectItem key={tz} value={tz}>
                    {tz}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="flex items-center space-x-2">
            <Switch
              id="isActive"
              name="isActive"
              defaultChecked={slot?.isActive === 1}
              data-testid="switch-is-active"
            />
            <Label htmlFor="isActive">Active</Label>
          </div>
        </div>

        <DialogFooter className="mt-6">
          <Button type="button" variant="outline" onClick={onCancel} data-testid="button-cancel">
            Cancel
          </Button>
          <Button type="submit" disabled={isPending} data-testid="button-submit">
            {isPending ? "Saving..." : slot ? "Update Slot" : "Create Slot"}
          </Button>
        </DialogFooter>
      </form>
    </DialogContent>
  );
}

