import { useState, useEffect, useRef } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { Card, CardContent, CardFooter, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { useToast } from "@/hooks/use-toast";
import { MessageCircle, Send, Plus, Trash2, Loader2, Calendar } from "lucide-react";
import { formatDistanceToNow } from "date-fns";
import { AppointmentBookingDialog } from "@/components/agent/appointment-booking-dialog";

interface Message {
  id: string;
  role: "user" | "assistant";
  message: string;
  createdAt: string;
  tokensUsed?: number | null;
  arrestRecordId?: string | null;
}

interface Session {
  sessionId: string;
  lastMessage: string;
  lastTimestamp: Date;
  messageCount: number;
}

interface ChatResponse {
  message: string;
  tokensUsed: number;
  sessionId: string;
  interaction: Message;
}

export default function AgentPage() {
  const { toast } = useToast();
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [inputMessage, setInputMessage] = useState("");
  const [isBookingDialogOpen, setIsBookingDialogOpen] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Load last session from localStorage on mount
  useEffect(() => {
    const savedSession = localStorage.getItem("agent_last_session");
    if (savedSession) {
      setCurrentSessionId(savedSession);
    }
  }, []);

  // Save current session to localStorage (skip temp IDs)
  useEffect(() => {
    if (currentSessionId && !currentSessionId.startsWith("temp-")) {
      localStorage.setItem("agent_last_session", currentSessionId);
    }
  }, [currentSessionId]);

  // Fetch sessions list
  const { data: sessionsData } = useQuery<{ sessions: Session[] }>({
    queryKey: ["/api/agent/sessions"],
  });

  // Fetch current session history
  const { data: historyData, isLoading: historyLoading } = useQuery<{
    sessionId: string;
    interactions: Message[];
    count: number;
  }>({
    queryKey: ["/api/agent/sessions", currentSessionId],
    enabled: !!currentSessionId,
  });

  // Send message mutation
  const sendMutation = useMutation({
    mutationFn: async (message: string) => {
      const response = await apiRequest("POST", "/api/agent/chat", {
        sessionId: currentSessionId || undefined,
        message,
      });
      return response as unknown as ChatResponse;
    },
    onMutate: async (message) => {
      // Generate temporary session ID for new conversations
      const tempSessionId = currentSessionId || `temp-${Date.now()}`;

      // Cancel outgoing queries to prevent race conditions
      await queryClient.cancelQueries({ queryKey: ["/api/agent/sessions", currentSessionId] });
      await queryClient.cancelQueries({ queryKey: ["/api/agent/sessions"] });

      // Create optimistic user message
      const optimisticUserMessage: Message = {
        id: `temp-user-${Date.now()}`,
        role: "user",
        message,
        createdAt: new Date().toISOString(),
        tokensUsed: null,
        arrestRecordId: null,
      };

      // Get current history (or create new one for new sessions)
      const previousHistory = queryClient.getQueryData<{
        sessionId: string;
        interactions: Message[];
        count: number;
      }>(["/api/agent/sessions", currentSessionId]);

      // Get previous sessions list
      const previousSessions = queryClient.getQueryData<{ sessions: Session[] }>(["/api/agent/sessions"]);

      // Optimistically update session history
      if (currentSessionId && previousHistory) {
        // Existing session - append message
        queryClient.setQueryData(["/api/agent/sessions", currentSessionId], {
          ...previousHistory,
          interactions: [...previousHistory.interactions, optimisticUserMessage],
          count: previousHistory.count + 1,
        });
      } else {
        // New session - create cache entry and set as current
        setCurrentSessionId(tempSessionId);
        queryClient.setQueryData(["/api/agent/sessions", tempSessionId], {
          sessionId: tempSessionId,
          interactions: [optimisticUserMessage],
          count: 1,
        });
      }

      // Optimistically update sessions list
      if (!currentSessionId) {
        const newSession: Session = {
          sessionId: tempSessionId,
          lastMessage: message,
          lastTimestamp: new Date(),
          messageCount: 1,
        };

        // Always create optimistic entry, even for first session
        if (previousSessions) {
          queryClient.setQueryData(["/api/agent/sessions"], {
            sessions: [newSession, ...previousSessions.sessions],
          });
        } else {
          // First session ever - create sessions cache
          queryClient.setQueryData(["/api/agent/sessions"], {
            sessions: [newSession],
          });
        }
      }

      // Clear input immediately
      setInputMessage("");

      // Return context for rollback
      return { previousHistory, previousSessions, tempSessionId, wasNewSession: !currentSessionId };
    },
    onSuccess: (data, variables, context) => {
      // Update current session with real ID from server
      if (context?.wasNewSession && context?.tempSessionId) {
        // Get current sessions list
        const currentSessions = queryClient.getQueryData<{ sessions: Session[] }>(["/api/agent/sessions"]);

        // Swap temp session with real session in sidebar
        if (currentSessions) {
          const updatedSessions = currentSessions.sessions.map(session =>
            session.sessionId === context.tempSessionId
              ? { ...session, sessionId: data.sessionId }
              : session
          );
          queryClient.setQueryData(["/api/agent/sessions"], {
            sessions: updatedSessions,
          });
        }

        // Get optimistic history cache
        const tempHistory = queryClient.getQueryData<{
          sessionId: string;
          interactions: Message[];
          count: number;
        }>(["/api/agent/sessions", context.tempSessionId]);

        // Move history from temp to real session
        if (tempHistory) {
          queryClient.setQueryData(["/api/agent/sessions", data.sessionId], {
            ...tempHistory,
            sessionId: data.sessionId,
          });
        }

        // Remove temporary session cache
        queryClient.removeQueries({ queryKey: ["/api/agent/sessions", context.tempSessionId] });

        // Set real session ID
        setCurrentSessionId(data.sessionId);
      }

      // Invalidate queries to get real server data
      queryClient.invalidateQueries({ queryKey: ["/api/agent/sessions"] });
      queryClient.invalidateQueries({ queryKey: ["/api/agent/sessions", data.sessionId] });
    },
    onError: (error: Error, variables, context) => {
      // Rollback optimistic updates
      if (context?.previousHistory && !context?.wasNewSession) {
        queryClient.setQueryData(["/api/agent/sessions", currentSessionId], context.previousHistory);
      } else if (context?.tempSessionId && context?.wasNewSession) {
        // Remove temporary session cache
        queryClient.removeQueries({ queryKey: ["/api/agent/sessions", context.tempSessionId] });
        // Reset session ID and clear from localStorage
        setCurrentSessionId(null);
        localStorage.removeItem("agent_last_session");
      }

      // Rollback sessions list
      if (context?.wasNewSession) {
        if (context?.previousSessions) {
          // Restore previous sessions list
          queryClient.setQueryData(["/api/agent/sessions"], context.previousSessions);
        } else {
          // Was first session ever - remove cache entirely
          queryClient.removeQueries({ queryKey: ["/api/agent/sessions"] });
        }
      }

      // Restore input
      setInputMessage(variables);

      toast({
        variant: "destructive",
        title: "Chat Error",
        description: error.message,
      });
    },
  });

  // Clear session mutation
  const clearMutation = useMutation({
    mutationFn: async (sessionId: string) => {
      return await apiRequest("POST", `/api/agent/sessions/${sessionId}/clear`, {});
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/agent/sessions"] });
      queryClient.invalidateQueries({ queryKey: ["/api/agent/sessions", currentSessionId] });
      toast({
        title: "Conversation Cleared",
        description: "Chat history has been deleted.",
      });
    },
    onError: (error: Error) => {
      toast({
        variant: "destructive",
        title: "Clear Failed",
        description: error.message,
      });
    },
  });

  const handleSend = () => {
    if (!inputMessage.trim()) return;
    sendMutation.mutate(inputMessage);
  };

  const handleNewSession = () => {
    // Clear current session from cache to ensure clean state
    if (currentSessionId) {
      queryClient.removeQueries({ queryKey: ["/api/agent/sessions", currentSessionId] });
    }
    setCurrentSessionId(null);
    localStorage.removeItem("agent_last_session");
  };

  const handleClearSession = () => {
    if (!currentSessionId) return;
    clearMutation.mutate(currentSessionId);
  };

  const sessions = sessionsData?.sessions || [];
  const messages = historyData?.interactions || [];

  // Auto-scroll to bottom when messages change
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollIntoView({ behavior: "smooth" });
    }
  }, [messages.length, sendMutation.isPending]);

  return (
    <div className="h-[calc(100vh-4rem)] flex gap-4 p-6 bg-background">
      {/* Left Panel - Session List */}
      <Card className="w-80 flex flex-col">
        <CardHeader className="flex flex-row items-center justify-between gap-2 space-y-0 pb-4">
          <CardTitle className="text-lg flex items-center gap-2">
            <MessageCircle className="h-5 w-5" />
            Sessions
          </CardTitle>
          <Button
            size="sm"
            onClick={handleNewSession}
            data-testid="button-new-session"
          >
            <Plus className="h-4 w-4 mr-1" />
            New
          </Button>
        </CardHeader>
        <CardContent className="flex-1 overflow-hidden p-0">
          <ScrollArea className="h-full px-6">
            <div className="space-y-2 pb-4">
              {sessions.length === 0 && (
                <p className="text-sm text-muted-foreground text-center py-8">
                  No conversations yet
                </p>
              )}
              {sessions.map((session) => (
                <button
                  key={session.sessionId}
                  onClick={() => setCurrentSessionId(session.sessionId)}
                  data-testid={`button-session-${session.sessionId}`}
                  className={`w-full text-left p-3 rounded-md transition-colors hover-elevate active-elevate-2 ${
                    currentSessionId === session.sessionId
                      ? "bg-accent"
                      : "bg-card"
                  }`}
                >
                  <div className="flex items-start justify-between gap-2 mb-1">
                    <p className="text-sm font-medium line-clamp-1">
                      {session.lastMessage}
                    </p>
                    <Badge variant="secondary" className="text-xs shrink-0">
                      {session.messageCount}
                    </Badge>
                  </div>
                  <p className="text-xs text-muted-foreground">
                    {formatDistanceToNow(new Date(session.lastTimestamp), { addSuffix: true })}
                  </p>
                </button>
              ))}
            </div>
          </ScrollArea>
        </CardContent>
      </Card>

      {/* Right Panel - Chat Interface */}
      <Card className="flex-1 flex flex-col">
        <CardHeader className="flex flex-row items-center justify-between gap-2 space-y-0 pb-4 border-b">
          <CardTitle className="text-lg">
            {currentSessionId ? "AI Assistant" : "New Conversation"}
          </CardTitle>
          <div className="flex items-center gap-2">
            <Button
              size="sm"
              variant="ghost"
              onClick={() => setIsBookingDialogOpen(true)}
              data-testid="button-open-booking-dialog"
            >
              <Calendar className="h-4 w-4 mr-1" />
              Schedule
            </Button>
            {currentSessionId && (
              <Button
                size="sm"
                variant="destructive"
                onClick={handleClearSession}
                disabled={clearMutation.isPending}
                data-testid="button-clear-session"
              >
                <Trash2 className="h-4 w-4 mr-1" />
                Clear
              </Button>
            )}
          </div>
        </CardHeader>

        <CardContent className="flex-1 overflow-hidden p-6">
          <ScrollArea className="h-full pr-4">
            {historyLoading ? (
              <div className="space-y-4">
                <Skeleton className="h-20 w-3/4" />
                <Skeleton className="h-20 w-3/4 ml-auto" />
                <Skeleton className="h-20 w-3/4" />
              </div>
            ) : messages.length === 0 ? (
              <div className="flex items-center justify-center h-full">
                <div className="text-center space-y-3">
                  <MessageCircle className="h-12 w-12 mx-auto text-muted-foreground" />
                  <p className="text-lg font-medium">Start a Conversation</p>
                  <p className="text-sm text-muted-foreground max-w-md">
                    Ask questions about arrest records, Florida statutes, or get help navigating the platform.
                  </p>
                </div>
              </div>
            ) : (
              <div className="space-y-4 pb-4">
                {messages.map((msg) => (
                  <div
                    key={msg.id}
                    className={`flex ${msg.role === "user" ? "justify-end" : "justify-start"}`}
                  >
                    <div
                      className={`max-w-[80%] rounded-lg p-4 ${
                        msg.role === "user"
                          ? "bg-primary text-primary-foreground"
                          : "bg-muted"
                      }`}
                      data-testid={`message-${msg.role}-${msg.id}`}
                    >
                      <p className="text-sm whitespace-pre-wrap">{msg.message}</p>
                      <div className="flex items-center gap-2 mt-2 text-xs opacity-70">
                        <span>
                          {formatDistanceToNow(new Date(msg.createdAt), { addSuffix: true })}
                        </span>
                        {msg.tokensUsed && (
                          <span>• {msg.tokensUsed} tokens</span>
                        )}
                      </div>
                    </div>
                  </div>
                ))}

                {/* Typing indicator */}
                {sendMutation.isPending && (
                  <div className="flex justify-start">
                    <div className="bg-muted rounded-lg p-4 max-w-[80%]">
                      <div className="flex gap-1">
                        <Skeleton className="h-2 w-2 rounded-full" />
                        <Skeleton className="h-2 w-2 rounded-full" />
                        <Skeleton className="h-2 w-2 rounded-full" />
                      </div>
                    </div>
                  </div>
                )}

                <div ref={scrollRef} />
              </div>
            )}
          </ScrollArea>
        </CardContent>

        <CardFooter className="border-t p-4">
          <div className="flex gap-2 w-full">
            <Textarea
              placeholder="Type your message..."
              value={inputMessage}
              onChange={(e) => setInputMessage(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter" && !e.shiftKey) {
                  e.preventDefault();
                  handleSend();
                }
              }}
              disabled={sendMutation.isPending}
              className="resize-none min-h-[60px]"
              data-testid="input-chat-message"
            />
            <Button
              onClick={handleSend}
              disabled={!inputMessage.trim() || sendMutation.isPending}
              size="icon"
              className="shrink-0 h-[60px] w-[60px]"
              data-testid="button-send-message"
            >
              {sendMutation.isPending ? (
                <Loader2 className="h-5 w-5 animate-spin" />
              ) : (
                <Send className="h-5 w-5" />
              )}
            </Button>
          </div>
        </CardFooter>
      </Card>

      {/* Appointment Booking Dialog */}
      <AppointmentBookingDialog
        open={isBookingDialogOpen}
        onOpenChange={setIsBookingDialogOpen}
        sessionId={currentSessionId}
        arrestRecordId={null}
      />
    </div>
  );
}

server/billing/stripe-service.ts.content:
import Stripe from "stripe";
import { storage } from "../storage";

// Plan definitions based on reference materials
export const SUBSCRIPTION_PLANS = {
  free: {
    name: "Free",
    price: 0,
    stripePriceId: null,
    features: [
      "Limited record view",
      "AI agent summary only",
      "Export disabled",
      "CRM disabled",
    ],
  },
  basic: {
    name: "Basic",
    price: 29.95,
    stripePriceId: process.env.STRIPE_PRICE_BASIC, // Set via Stripe dashboard
    features: [
      "View-only AI Summary",
      "Alerts enabled",
      "Limited exports",
    ],
  },
  standard: {
    name: "Standard",
    price: 59.95,
    stripePriceId: process.env.STRIPE_PRICE_STANDARD,
    features: [
      "Full record access",
      "PDF/CSV export",
      "AI assistant",
      "CRM delivery",
    ],
  },
  pro: {
    name: "Pro",
    price: 89.95,
    stripePriceId: process.env.STRIPE_PRICE_PRO,
    features: [
      "Everything in Standard",
      "AI trainer access",
      "Fine-tune tools",
      "Advanced analytics",
    ],
  },
  elite: {
    name: "Elite",
    price: 189.95,
    stripePriceId: process.env.STRIPE_PRICE_ELITE,
    features: [
      "Everything in Pro",
      "Real-time court watch",
      "Appointment matching",
      "Priority support",
      "Multi-LLM access",
    ],
  },
} as const;

export type PlanTier = keyof typeof SUBSCRIPTION_PLANS;

// Initialize Stripe client
let stripeClient: Stripe | null = null;

export function getStripeClient(): Stripe {
  if (!stripeClient) {
    const secretKey = process.env.STRIPE_SECRET_KEY;

    if (!secretKey) {
      throw new Error('STRIPE_SECRET_KEY not configured');
    }

    stripeClient = new Stripe(secretKey, {
      apiVersion: "2025-10-29.clover",
    });
  }
  return stripeClient;
}

export class BillingService {
  /**
   * Create or retrieve Stripe customer for user
   */
  async ensureCustomer(userId: string, email: string, name?: string): Promise<string> {
    const user = await storage.getUserById(userId);

    if (user?.stripeCustomerId) {
      return user.stripeCustomerId;
    }

    const stripe = getStripeClient();
    const customer = await stripe.customers.create({
      email,
      name: name || email.split('@')[0],
      metadata: {
        userId,
      },
    });

    await storage.updateUserStripeInfo(userId, {
      stripeCustomerId: customer.id,
    });

    return customer.id;
  }

  /**
   * Create payment intent for one-time payment
   */
  async createPaymentIntent(params: {
    userId: string;
    amount: number;
    description: string;
  }): Promise<{ clientSecret: string; paymentIntentId: string }> {
    const stripe = getStripeClient();
    const user = await storage.getUserById(params.userId);

    if (!user) {
      throw new Error('User not found');
    }

    const customerId = await this.ensureCustomer(
      params.userId, 
      user.email, 
      user.email.split('@')[0]
    );

    const paymentIntent = await stripe.paymentIntents.create({
      amount: Math.round(params.amount * 100), // Convert to cents
      currency: "usd",
      customer: customerId,
      description: params.description,
      metadata: {
        userId: params.userId,
      },
    });

    return {
      clientSecret: paymentIntent.client_secret!,
      paymentIntentId: paymentIntent.id,
    };
  }

  /**
   * Create Stripe Checkout Session for subscription
   */
  async createCheckoutSession(params: {
    userId: string;
    plan: PlanTier;
    successUrl: string;
    cancelUrl: string;
  }): Promise<{
    sessionId: string;
    url: string;
  }> {
    const stripe = getStripeClient();
    const user = await storage.getUserById(params.userId);

    if (!user) {
      throw new Error('User not found');
    }

    const planConfig = SUBSCRIPTION_PLANS[params.plan];

    if (params.plan === 'free' || !planConfig.stripePriceId) {
      throw new Error('Cannot create subscription for free plan or unconfigured plan');
    }

    const customerId = await this.ensureCustomer(
      params.userId,
      user.email,
      user.email.split('@')[0]
    );

    // Create Stripe Checkout Session
    const session = await stripe.checkout.sessions.create({
      customer: customerId,
      mode: 'subscription',
      line_items: [{
        price: planConfig.stripePriceId,
        quantity: 1,
      }],
      success_url: params.successUrl,
      cancel_url: params.cancelUrl,
      metadata: {
        userId: params.userId,
        plan: params.plan,
      },
      subscription_data: {
        metadata: {
          userId: params.userId,
          plan: params.plan,
        },
      },
    });

    return {
      sessionId: session.id,
      url: session.url!,
    };
  }

  /**
   * Get or create billing portal session
   */
  async createPortalSession(params: {
    userId: string;
    returnUrl: string;
  }): Promise<{ url: string }> {
    const stripe = getStripeClient();
    const user = await storage.getUserById(params.userId);

    if (!user || !user.stripeCustomerId) {
      throw new Error('No Stripe customer found');
    }

    const session = await stripe.billingPortal.sessions.create({
      customer: user.stripeCustomerId,
      return_url: params.returnUrl,
    });

    return { url: session.url };
  }

  /**
   * Handle Stripe webhook events
   */
  async handleWebhook(event: Stripe.Event): Promise<void> {
    switch (event.type) {
      case 'customer.subscription.updated':
      case 'customer.subscription.created': {
        const subscription = event.data.object as Stripe.Subscription;
        await this.handleSubscriptionChange(subscription);
        break;
      }

      case 'customer.subscription.deleted': {
        const subscription = event.data.object as Stripe.Subscription;
        await this.handleSubscriptionCanceled(subscription);
        break;
      }

      case 'invoice.paid': {
        const invoice = event.data.object as Stripe.Invoice;
        console.log(`Invoice paid: ${invoice.id} for customer ${invoice.customer}`);
        break;
      }

      case 'invoice.payment_failed': {
        const invoice = event.data.object as Stripe.Invoice;
        console.log(`Invoice payment failed: ${invoice.id}`);
        break;
      }

      default:
        console.log(`Unhandled event type: ${event.type}`);
    }
  }

  /**
   * Handle subscription change webhook
   */
  private async handleSubscriptionChange(subscription: Stripe.Subscription): Promise<void> {
    const userId = subscription.metadata.userId;
    const plan = subscription.metadata.plan as PlanTier || 'free';

    if (!userId) {
      console.warn('Subscription missing userId metadata:', subscription.id);
      return;
    }

    await storage.updateUserStripeInfo(userId, {
      stripeSubscriptionId: subscription.id,
      subscriptionStatus: subscription.status,
      plan,
      subscriptionCurrentPeriodEnd: (subscription as any).current_period_end as number,
    });

    console.log(`✓ Updated subscription for user ${userId}: ${plan} (${subscription.status})`);
  }

  /**
   * Handle subscription canceled webhook
   */
  private async handleSubscriptionCanceled(subscription: Stripe.Subscription): Promise<void> {
    const userId = subscription.metadata.userId;

    if (!userId) {
      console.warn('Subscription missing userId metadata:', subscription.id);
      return;
    }

    await storage.updateUserStripeInfo(userId, {
      subscriptionStatus: 'canceled',
      plan: 'free',
      subscriptionCurrentPeriodEnd: null,
    });

    console.log(`✓ Canceled subscription for user ${userId}`);
  }
}

export const billingService = new BillingService();

server/llm/router.ts.content:
import OpenAI from "openai";
import Anthropic from "@anthropic-ai/sdk";
import { GoogleGenAI } from "@google/genai";

// LLM Provider Types
export type LLMProvider = 'openai' | 'claude' | 'gemini';

export interface LLMConfig {
  provider: LLMProvider;
  model: string;
  maxTokens?: number;
  temperature?: number;
  timeoutMs?: number;
}

export interface LLMResponse {
  content: string;
  provider: LLMProvider;
  model: string;
  tokensUsed?: number;
  latencyMs: number;
}

export interface LLMError {
  provider: LLMProvider;
  error: string;
  retryable: boolean;
}

// Default configurations for each provider
const DEFAULT_CONFIGS: Record<LLMProvider, LLMConfig> = {
  openai: {
    provider: 'openai',
    model: 'gpt-4o-mini',
    maxTokens: 1000,
    temperature: 0.7,
    timeoutMs: 15000,
  },
  claude: {
    provider: 'claude',
    model: 'claude-sonnet-4-5',
    maxTokens: 1000,
    temperature: 0.7,
    timeoutMs: 15000,
  },
  gemini: {
    provider: 'gemini',
    model: 'gemini-2.5-flash',
    maxTokens: 1000,
    temperature: 0.7,
    timeoutMs: 15000,
  },
};

// Initialize clients (lazy loading)
let openaiClient: OpenAI | null = null;
let anthropicClient: Anthropic | null = null;
let geminiClient: GoogleGenAI | null = null;

function getOpenAIClient(): OpenAI {
  if (!openaiClient) {
    const apiKey = process.env.AI_INTEGRATIONS_OPENAI_API_KEY;
    const baseURL = process.env.AI_INTEGRATIONS_OPENAI_BASE_URL;

    if (!apiKey || !baseURL) {
      throw new Error('OpenAI AI Integrations not configured');
    }

    openaiClient = new OpenAI({ apiKey, baseURL });
  }
  return openaiClient;
}

function getAnthropicClient(): Anthropic {
  if (!anthropicClient) {
    const apiKey = process.env.AI_INTEGRATIONS_ANTHROPIC_API_KEY;
    const baseURL = process.env.AI_INTEGRATIONS_ANTHROPIC_BASE_URL;

    if (!apiKey || !baseURL) {
      throw new Error('Anthropic AI Integrations not configured');
    }

    anthropicClient = new Anthropic({ apiKey, baseURL });
  }
  return anthropicClient;
}

function getGeminiClient(): GoogleGenAI {
  if (!geminiClient) {
    const apiKey = process.env.AI_INTEGRATIONS_GEMINI_API_KEY;

    if (!apiKey) {
      throw new Error('Gemini AI Integrations not configured');
    }

    geminiClient = new GoogleGenAI({ apiKey });
  }
  return geminiClient;
}

// Call OpenAI with timeout
async function callOpenAI(
  prompt: string,
  systemPrompt: string,
  config: LLMConfig
): Promise<LLMResponse> {
  const startTime = Date.now();
  const client = getOpenAIClient();

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), config.timeoutMs);

  try {
    const response = await client.chat.completions.create({
      model: config.model,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: prompt },
      ],
      max_tokens: config.maxTokens,
      temperature: config.temperature,
    }, { signal: controller.signal });

    clearTimeout(timeoutId);

    return {
      content: response.choices[0]?.message?.content || '',
      provider: 'openai',
      model: config.model,
      tokensUsed: response.usage?.total_tokens,
      latencyMs: Date.now() - startTime,
    };
  } catch (error: any) {
    clearTimeout(timeoutId);
    throw error;
  }
}

// Call Anthropic with timeout
async function callAnthropic(
  prompt: string,
  systemPrompt: string,
  config: LLMConfig
): Promise<LLMResponse> {
  const startTime = Date.now();
  const client = getAnthropicClient();

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), config.timeoutMs);

  try {
    const response = await client.messages.create({
      model: config.model,
      max_tokens: config.maxTokens || 1000,
      temperature: config.temperature,
      system: systemPrompt,
      messages: [
        { role: 'user', content: prompt },
      ],
    }, { signal: controller.signal });

    clearTimeout(timeoutId);

    const content = response.content[0];
    return {
      content: content.type === 'text' ? content.text : '',
      provider: 'claude',
      model: config.model,
      tokensUsed: (response.usage?.input_tokens || 0) + (response.usage?.output_tokens || 0),
      latencyMs: Date.now() - startTime,
    };
  } catch (error: any) {
    clearTimeout(timeoutId);
    throw error;
  }
}

// Call Gemini with timeout
async function callGemini(
  prompt: string,
  systemPrompt: string,
  config: LLMConfig
): Promise<LLMResponse> {
  const startTime = Date.now();
  const client = getGeminiClient();

  // Build proper contents structure
  const fullPrompt = systemPrompt ? `${systemPrompt}\n\n${prompt}` : prompt;

  const timeoutPromise = new Promise<never>((_, reject) => {
    setTimeout(() => reject(new Error('Timeout')), config.timeoutMs);
  });

  try {
    const result = await Promise.race([
      client.models.generateContent({
        model: config.model,
        contents: [
          {
            role: 'user',
            parts: [{ text: fullPrompt }]
          }
        ],
        config: {
          maxOutputTokens: config.maxTokens,
          temperature: config.temperature,
        },
      }),
      timeoutPromise,
    ]);

    return {
      content: result.text || '',
      provider: 'gemini',
      model: config.model,
      tokensUsed: result.usageMetadata?.totalTokenCount || 0,
      latencyMs: Date.now() - startTime,
    };
  } catch (error: any) {
    throw error;
  }
}

/**
 * Get AI response with automatic fallback between providers
 * @param prompt - User prompt
 * @param systemPrompt - System instructions
 * @param fallbackOrder - Order of providers to try (default: openai -> claude -> gemini)
 * @param customConfigs - Optional custom configs per provider
 */
export async function getResponse(
  prompt: string,
  systemPrompt: string = '',
  fallbackOrder: LLMProvider[] = ['openai', 'claude', 'gemini'],
  customConfigs?: Partial<Record<LLMProvider, Partial<LLMConfig>>>
): Promise<LLMResponse> {
  const errors: LLMError[] = [];

  for (const provider of fallbackOrder) {
    const defaultConfig = DEFAULT_CONFIGS[provider];
    const customConfig = customConfigs?.[provider] || {};
    const config: LLMConfig = { ...defaultConfig, ...customConfig };

    try {
      let response: LLMResponse;

      switch (provider) {
        case 'openai':
          response = await callOpenAI(prompt, systemPrompt, config);
          break;
        case 'claude':
          response = await callAnthropic(prompt, systemPrompt, config);
          break;
        case 'gemini':
          response = await callGemini(prompt, systemPrompt, config);
          break;
        default:
          throw new Error(`Unknown provider: ${provider}`);
      }

      // Success! Return immediately
      console.log(`✓ LLM Response from ${provider} (${response.latencyMs}ms, ${response.tokensUsed} tokens)`);
      return response;

    } catch (error: any) {
      const errorMsg = error.message || String(error);
      const isRetryable = 
        errorMsg.includes('timeout') ||
        errorMsg.includes('429') || 
        errorMsg.includes('quota') ||
        errorMsg.includes('overloaded') ||
        errorMsg.includes('rate limit');

      errors.push({
        provider,
        error: errorMsg,
        retryable: isRetryable,
      });

      console.warn(`✗ LLM ${provider} failed: ${errorMsg} (retryable: ${isRetryable})`);

      // Continue to next provider
      continue;
    }
  }

  // All providers failed
  throw new Error(
    `All LLM providers failed. Errors: ${JSON.stringify(errors, null, 2)}`
  );
}

/**
 * Check health of all configured LLM providers
 */
export async function checkLLMHealth(): Promise<Record<LLMProvider, boolean>> {
  const health: Record<LLMProvider, boolean> = {
    openai: false,
    claude: false,
    gemini: false,
  };

  const testPrompt = "Say 'OK'";
  const testSystem = "You are a test assistant.";

  // Test each provider in parallel
  const tests = [
    (async () => {
      try {
        await callOpenAI(testPrompt, testSystem, { 
          ...DEFAULT_CONFIGS.openai, 
          timeoutMs: 5000 
        });
        health.openai = true;
      } catch (e: any) {
        console.debug(`OpenAI health check failed: ${e.message}`);
      }
    })(),
    (async () => {
      try {
        await callAnthropic(testPrompt, testSystem, { 
          ...DEFAULT_CONFIGS.claude, 
          timeoutMs: 5000 
        });
        health.claude = true;
      } catch (e: any) {
        console.debug(`Claude health check failed: ${e.message}`);
      }
    })(),
    (async () => {
      try {
        await callGemini(testPrompt, testSystem, { 
          ...DEFAULT_CONFIGS.gemini, 
          timeoutMs: 5000 
        });
        health.gemini = true;
      } catch (e: any) {
        console.debug(`Gemini health check failed: ${e.message}`);
      }
    })(),
  ];

  await Promise.allSettled(tests);

  return health;
}

